<?php
require_once __DIR__.'/../includes/auth.php';require_admin();
$rows=db()->query("SELECT c.*,COUNT(d.id) total,SUM(d.status='accepted') accepted,SUM(d.status='failed') failed,SUM(d.opened_at IS NOT NULL) opened,SUM(d.clicked_at IS NOT NULL) clicked FROM newsletter_campaigns c LEFT JOIN newsletter_deliveries d ON d.campaign_id=c.id GROUP BY c.id ORDER BY c.created_at DESC")->fetchAll();require __DIR__.'/_header.php';?>
<div class="admin-page-head"><h1>Newsletter Campaigns</h1><a class="primary button-link" href="newsletter_campaign_edit.php">New Campaign</a></div><div class="settings-card"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Campaign</th><th>Status</th><th>Recipients</th><th>Accepted</th><th>Failed</th><th>Opened</th><th>Clicked</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><br><small><?=e($r['subject'])?></small></td><td><?=e(ucfirst($r['status']))?></td><td><?=(int)$r['total']?></td><td><?=(int)$r['accepted']?></td><td><?=(int)$r['failed']?></td><td><?=(int)$r['opened']?></td><td><?=(int)$r['clicked']?></td><td><a class="secondary button-link" href="newsletter_campaign_edit.php?id=<?=$r['id']?>">Open</a></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><p>No campaigns yet.</p><?php endif;?></div><?php require __DIR__.'/_footer.php';?>
